function WorldMap() {
  // Real country boundaries (Natural Earth 110m via world-atlas), projected
  // equirectangular and fitted to a 1000x500 box — not hand-drawn.
  return (
    <svg viewBox="0 0 1000 500" preserveAspectRatio="none" className="w-full h-full block">
      <path d={LAND_D} fill="#3A3A3A" stroke="none" />
      <path d={BORDERS_D} fill="none" stroke="#565656" strokeWidth="0.6" />
    </svg>
  );
}

